#quantum-canvas { position: fixed; top: 0; left: 0; width: 100%; height: 100vh; z-index: 1; pointer-events: none; }
.q-text-layer {
  position: fixed; top: 0; left: 0; width: 100%; height: 100vh;
  display: flex; flex-direction: column; align-items: center; justify-content: center; z-index: 2; pointer-events: none;
}
.q-msg {
  position: absolute; color: #fff; font-size: 20px; font-weight: bold; text-align: center;
  opacity: 0; transition: opacity 0.5s; text-shadow: 0 5px 15px rgba(0,255,204,0.8);
}

jsCode:
const mc = document.getElementById('container');
mc.style.cssText = 'width:100%;height:100%;overflow-y:auto;background:#030014;position:relative;';

mc.innerHTML = `
  <div class="quantum-wrap">
    <canvas id="quantum-canvas"></canvas>
    <div class="q-text-layer">
      <div id="q1" class="q-msg" style="top:15%; color:#aaa;">Quantum Core Active ↓</div>
      <div id="q2" class="q-msg" style="font-size:40px; color:#ff007f;">UNLEASH POWER</div>
      <div id="q3" class="q-msg" style="font-size:55px; color:#00ffcc; top:75%;">ZYNK</div>
    </div>
  </div>
`;

const qCvs = document.getElementById('quantum-canvas');
const qCtx = qCvs.getContext('2d');
let qW, qH;
let qParticles = [], targetTxtPts = [];
const qCount = 800;

function getTxtPts(txt, size) {
  const tc = document.createElement('canvas');
  tc.width = qW; tc.height = qH;
  const tctx = tc.getContext('2d');
  tctx.fillStyle = 'white'; tctx.font = `900 ${size}px sans-serif`;
  tctx.textAlign = 'center'; tctx.textBaseline = 'middle';
  tctx.fillText(txt, qW/2, qH/2);
  const data = tctx.getImageData(0,0,qW,qH).data;
  let pts = [];
  for(let y=0; y<qH; y+=7){
    for(let x=0; x<qW; x+=7){
      if(data[(y*qW+x)*4+3] > 128) pts.push({x:x, y:y});
    }
  }
  return pts.length ? pts : [{x: qW/2, y: qH/2}];
}

function initQ() {
  qW = qCvs.width = window.innerWidth;
  qH = qCvs.height = window.innerHeight;
  targetTxtPts = getTxtPts('ZYNK', Math.min(qW/3, 100));

  qParticles = [];
  for(let i=0; i<qCount; i++){
    qParticles.push({
      x: qW/2, y: qH/2, 
      angle: Math.random() * Math.PI * 2,
      baseRadius: Math.random() * 80 + 20,
      c: `hsl(${180 + Math.random()*80}, 100%, 60%)` // Cyan & Blue
    });
  }
}
initQ(); window.addEventListener('resize', initQ);

let qProg = 0;
mc.addEventListener('scroll', () => {
  qProg = mc.scrollTop / (mc.scrollHeight - mc.clientHeight);
  document.getElementById('q1').style.opacity = (qProg < 0.2) ? 1 : 0;
  document.getElementById('q2').style.opacity = (qProg > 0.35 && qProg < 0.6) ? 1 : 0;
  document.getElementById('q3').style.opacity = (qProg > 0.8) ? 1 : 0;
});

function lerp(a, b, t) { return a + (b - a) * t; }

function drawQ() {
  qCtx.fillStyle = 'rgba(3, 0, 20, 0.3)'; 
  qCtx.fillRect(0,0,qW,qH);

  let time = Date.now() * 0.002;

  for(let i=0; i<qCount; i++){
    let p = qParticles[i];
    let tx, ty;

    if(qProg < 0.5) {
      // પ્રવાહી ગોળો (Liquid Orb)
      let currentScale = 1 + (qProg * 3); // સ્ક્રોલથી મોટો થશે
      let wave = Math.sin(p.angle * 4 + time) * 15;
      let r = (p.baseRadius + wave) * currentScale;
      tx = qW/2 + Math.cos(p.angle + time*0.5) * r;
      ty = qH/2 + Math.sin(p.angle + time*0.5) * r;
    } else {
      // વિસ્ફોટ અને ટેક્સ્ટ મોર્ફિંગ
      let mProg = (qProg - 0.5) * 2;
      let tPt = targetTxtPts[i % targetTxtPts.length];

      let explodeX = qW/2 + Math.cos(p.angle) * qW;
      let explodeY = qH/2 + Math.sin(p.angle) * qW;

      tx = lerp(explodeX, tPt.x, mProg);
      ty = lerp(explodeY, tPt.y, mProg);
    }

    p.x += (tx - p.x) * 0.1; p.y += (ty - p.y) * 0.1;
    qCtx.beginPath(); qCtx.arc(p.x, p.y, 2, 0, Math.PI*2);
    qCtx.fillStyle = p.c; qCtx.fill();
  }
  requestAnimationFrame(drawQ);
}
drawQ();
